	["BOSS_CULT_LEADER_NAME"] = "Seeress Mydrias",
	["BOSS_GRYMBEARD_DESCRIPTION"] = "Người lùn kiêu ngạo, ích kỷ, gần như điên loạn và cực kỳ nguy hiểm.",
	["BOSS_GRYMBEARD_EXTRA"] = "- Phóng nắm đấm tên lửa vào đơn vị của người chơi",
	["BOSS_GRYMBEARD_NAME"] = "Grymbeard",
	["BOSS_MACHINIST_DESCRIPTION"] = "Trò chơi đeo trên những phát minh mới nhất của họ để theo đuổi kẻ địch, hạ xuống lửa và kim loại mưa.",
	["BOSS_MACHINIST_EXTRA"] = "- Bay\n- Bắn phế liệu vào đơn vị của người chơi",
	["BOSS_MACHINIST_NAME"] = "Grymbeard",
	["BOSS_MURGLUM_DESCRIPTION"] = "Con rồng dung nham cái mạnh mẽ nhất từng được biết đến. Từng bị Vez'nan điều khiển, Murglun nay đã tự do và tự nguyện theo chủ mới. Cô là một tai họa rực lửa, với cơn giận gần như không thể dập tắt.",
	["BOSS_MURGLUM_EXTRA"] = "- Đổ bóng lửa trên đường\n- Tháp phòng thủ bị chặn\n- Đánh bại đơn vị, gây sát thương diện rộng",
	["BOSS_MURGLUM_NAME"] = "Murglun",
	["BOSS_NAVIRA_DESCRIPTION"] = "Navira đã nhiễm sức mạnh cấm kỵ và đánh mất ân sủng của nữ thần. Hắn dùng ma thuật chết chóc để khôi phục vinh quang của tộc tinh linh.",
	["BOSS_NAVIRA_EXTRA"] = "- Bắn bóng lửa chặn tháp phòng thủ\n- Thay đổi thành một cơn bão không thể ngăn chặn",
	["BOSS_NAVIRA_NAME"] = "Navira",
	["BOSS_PIG_DESCRIPTION"] = "Tự đóng cửa như là đỉnh của động vật, có thể sử dụng một kẻ địch khổng lồ.",
	["BOSS_PIG_EXTRA"] = "- Nhảy xa qua các đường\n- Giáp thấp",
	["BOSS_PIG_NAME"] = "Goregrind",
	["BOSS_PRINCESS_IRON_FAN_DESCRIPTION"] = "Cảm giác như một con dao lạnh.\nHôn nhân là nữ hoàng, thần fan cũng là quỷ.\nCó thể tiêu diệt lửa, vui vẻ.",
	["BOSS_PRINCESS_IRON_FAN_EXTRA"] = "- Tạo phân thân\n- Nhốt anh hùng trong bình\n- Biến tháp thành điểm sinh quân địch",
	["BOSS_PRINCESS_IRON_FAN_NAME"] = "Princess Iron Fan",
	["BOSS_REDBOY_TEEN_DESCRIPTION"] = "Vua quỷ, trẻ điên.\nNỗi hào hứng, ngày hào hào.\nĐốt lửa thật, chơi súng tốt.",
	["BOSS_REDBOY_TEEN_EXTRA"] = "- Đòn đánh gây sát thương diện rộng lớn\n- Ra lệnh cho rồng làm choáng tháp\n- Giáp và kháng phép thấp",
	["BOSS_REDBOY_TEEN_NAME"] = "Red Boy",
