	["COMIC_12_4_KR6_KR6"] = "Xin hãy nói với tôi những gì đã xảy ra!",
	["COMIC_12_5_KR5_KR5"] = "Ăn Ăn, Ăn",
	["COMIC_12_5_KR6_KR6"] = "Sau đó, tôi sẽ giải thích cho bạn.",
	["COMIC_12_6_KR5_KR5"] = "Tôi chắc chắn là một nghệ sĩ.",
	["COMIC_12_6_KR6_KR6"] = "Bây giờ hãy nhanh chóng đi.",
	["COMIC_12_7_KR6_KR6"] = "Đang chờ anh, hơn tôi.",
	["COMIC_13_1_KR5_KR5"] = "Có người nói đây là một hành động điên rồ.",
	["COMIC_13_2_KR5_KR5"] = "Vũ khí này không thể hoàn thành được.",
	["COMIC_13_3_KR5_KR5"] = "Họ sẽ sớm nhận ra mình đã sai đến mức nào.",
	["COMIC_13_4_KR5_KR5"] = "Và thả xuống trước mặt thiên tài!",
	["COMIC_14_1_KR5_KR5"] = "Làm thế nào để đối phó với những người này?",
	["COMIC_14_2_KR5_KR5"] = "Gửi cho tôi!",
	["COMIC_14_3_KR5_KR5"] = "Tôi biết một nơi tốt.",
	["COMIC_14_4_KR5_KR5"] = "Nơi gọi là tốt?",
	["COMIC_14_5_KR5_KR5"] = "Lời bài hát: Gửi Thức Dỡ Ở Cung Cung?",
	["COMIC_14_6_KR5_KR5"] = "Đúng là, bạn nhỏ của tôi.",
	["COMIC_14_7_KR5_KR5"] = "Đầu anh có thể làm những việc lớn!",
	["COMIC_15_10_KR5_KR5"] = "Tuy nhiên, họ không tốt.",
	["COMIC_15_1_KR5_KR5"] = "Ở một nơi nào đó trên núi.",
	["COMIC_15_2_KR5_KR5"] = "Hỡi GOBLIN!",
	["COMIC_15_3_KR5_KR5"] = "Làm việc!",
	["COMIC_15_4_KR5_KR5"] = "Bạn phải đưa tin trở lại.",
	["COMIC_15_5_KR5_KR5"] = "Cần thêm các nhà điều tra. Các nhà giáo này vẫn đang đi bộ, khiến chúng ta không yên tâm.",
	["COMIC_15_6_KR5_KR5"] = "Có thể gửi một số con quái vật, họ.",
	["COMIC_15_7_KR5_KR5"] = "Lãnh đạo bóng tối! thông tin khẩn cấp!",
	["COMIC_15_8_KR5_KR5"] = "Ồ.",
	["COMIC_15_9_KR5_KR5"] = "Tôi đã tìm thấy các nhân viên điều tra của tôi.",
	["COMIC_16_1_KR5_KR5"] = "Sự thù hận của tôi sẽ được báo cáo!",
	["COMIC_16_2_KR5_KR5"] = "Cô nói chị em của tôi.hư?",
	["COMIC_17_10_KR5_KR5"] = "Nếu không ngăn cản, trời sẽ nguy hiểm!",
	["COMIC_17_11_KR5_KR5"] = "Đó là việc chúng ta cần giúp đỡ!",
	["COMIC_17_12_KR5_KR5"] = "Oh, đó là tất nhiên.",
	["COMIC_17_13_KR5_KR5"] = "Tất nhiên là.",
	["COMIC_17_1_KR5_KR5"] = "Đẹp quá buổi chiều!",
	["COMIC_17_2_KR5_KR5"] = "Tôi sẽ quen với sự yên tĩnh này.",
	["COMIC_17_3_KR5_KR5"] = "Tốt nhất là không.",
	["COMIC_17_4_KR5_KR5"] = "Sun Khải Huyền!? Không cần phải “làm sáng” như thế này.",
	["COMIC_17_5_KR5_KR5"] = "Hai người, không quan trọng!",
	["COMIC_17_6_KR5_KR5"] = "Lúc trước, ông già đã lên lưng con rắn.",
	["COMIC_17_7_KR5_KR5"] = "Cả ba thành viên gia đình Ma vương đột nhiên xuất hiện!",
	["COMIC_17_8_KR5_KR5"] = "Không phải là một người đàn ông dũng cảm, thật đáng tiếc.",
	["COMIC_17_9_KR5_KR5"] = "Tôi đã giữ những con đàng mà tôi đã lấy đi!",
	["COMIC_18_1_KR5_KR5"] = "Vùng bờ biển của Vua.",
	["COMIC_18_2_KR5_KR5"] = "Khóa mục tiêu!",
	["COMIC_18_3_KR5_KR5"] = "Tất cả súng, bắn súng!",
	["COMIC_18_4_KR5_KR5"] = "Bỏ trứng, cười!",
	["COMIC_18_5_KR5_KR5"] = "Đối với Linirea!",
	["COMIC_18_6_KR5_KR5"] = "Trở lại sau! Con trai tôi đi đường!",
	["COMIC_19_1_KR5_KR5"] = "Cái này không nên để ngươi quan tâm!",
	["COMIC_19_2_KR5_KR5"] = "- Đúng rồi, hãy giữ lại, con khỉ.",
	["COMIC_19_3_KR5_KR5"] = "Đức Kitô khôn ngoan!",
	["COMIC_19_4_KR5_KR5"] = "Tôi phải làm gì với ba người?",
	["COMIC_1_10_KR6_KR6"] = "Tuy nhiên, tất cả điều này vẫn chưa kết thúc.",
	["COMIC_1_11_KR6_KR6"] = "Để có một tương lai tốt đẹp, tôi sẽ đi một chuyến đi hoàn toàn mới!",
	["COMIC_1_1_KR3"] = "Chuyện bắt đầu từ rất lâu trước đây, ở một lục địa xa xôi…",
	["COMIC_1_1_KR5"] = "Một tháng trước, chúng tôi đã đến đây để tìm kiếm vị vua đã mất tích của chúng tôi.",
	["COMIC_1_1_KR6_KR6"] = "“Chúng tôi quá ngây thơ, chúng tôi tưởng tượng rằng một vị vua quỷ đã từng thay đổi sự dữ, tin rằng hòa bình lâu dài cuối cùng sẽ đến.",
	["COMIC_1_2B_KR5"] = "Ông bị ma thuật đen Vez'nan trục xuất.",
	["COMIC_1_2_KR3"] = "…nơi mọi người sống trong hòa bình.",
	["COMIC_1_2_KR6_KR6"] = "Tôi. không thể chịu đựng được!",
	["COMIC_1_3_KR2"] = "Đám cờ chiến tranh!",
	["COMIC_1_3_KR6_KR6"] = "Jerry, bây giờ là rồi.",
	["COMIC_1_4_KR2"] = "Không thể giữ được bao lâu! phía đông sẽ bị bắt!",
	["COMIC_1_4_KR5"] = "Để phục hồi sức mạnh, chúng tôi tìm thấy một nơi như một trại.",
	["COMIC_1_4_KR6_KR6"] = "- Thưa Thầy, Thầy có chắc không?",
	["COMIC_1_5_KR2"] = "Ấy Ấy!",
	["COMIC_1_5_KR3"] = "Nhưng rồi…",
	["COMIC_1_5_KR5"] = "Nghỉ ngơi một phút.",
	["COMIC_1_5_KR6_KR6"] = "Chỉ có một cái bắn thôi.",
	["COMIC_1_6_KR3"] = "…hòa bình không kéo dài mãi mãi!",
	["COMIC_1_6_KR6_KR6"] = "Và đó là mục tiêu của Thần Khí.",
	["COMIC_1_7_KR6_KR6"] = "Hãy nhanh đi, bạn cũ!",
	["COMIC_1_8_KR5"] = "Giờ thì ngày bình yên đã kết thúc.",
	["COMIC_1_8_KR6_KR6"] = "Tôi đã làm dịu và trả giá rất đắt.",
	["COMIC_1_9_KR6_KR6"] = "Ồ, Ồ, H!",
	["COMIC_20_10_KR5_KR5"] = "Họ dường như được tạo ra bởi máu rạn nát!",
	["COMIC_20_11_KR5_KR5"] = "Sao tôi không nghĩ đến điều này?",
	["COMIC_20_1_KR5_KR5"] = "Sau đó, trước cửa của con rồng.",
	["COMIC_20_2_KR5_KR5"] = "Nó trông giống như những chữ của người con rồng cổ đại.",
	["COMIC_20_3_KR5_KR5"] = "Tôi là Oryon, người bảo vệ đất nước đám mây.",
	["COMIC_20_4_KR5_KR5"] = "Khẩn cấp, có tin xấu!",
	["COMIC_20_5_KR5_KR5"] = "Lunary đang bảo vệ Nữ hoàng Trái Đất, cô ấy cần sự hỗ trợ của chúng tôi!",
	["COMIC_20_6_KR5_KR5"] = "Thượng Đế!",
	["COMIC_20_7_KR5_KR5"] = "Hãy để liên minh giúp đỡ!",
	["COMIC_20_8_KR5_KR5"] = "Oh.",
	["COMIC_20_9_KR5_KR5"] = "- Thưa ông, hãy đến thăm các tướng!",
	["COMIC_21_1_KR5_KR5"] = "Cả quân đội chú ý!",
	["COMIC_21_2_KR5_KR5"] = "Bảo vệ nơi thánh giá bất cứ giá nào!",
	["COMIC_21_3_KR5_KR5"] = "Đây là đường phòng thủ cuối cùng của chúng tôi!",
	["COMIC_21_4_KR5_KR5"] = "Cảnh sát không thể chịu đựng được.",
	["COMIC_21_5_KR5_KR5"] = "Nhanh đến! Orion!",
	["COMIC_21_6_KR5_KR5"] = "Hahah! Tôi nghĩ rằng sẽ hơi khó khăn.",
	["COMIC_22_1_KR5_KR5"] = "Tôi sẽ trở thành vua của con rồng! Hahah!",
	["COMIC_22_2_KR5_KR5"] = "Quân ma của tôi ở đâu?",
	["COMIC_22_3_KR5_KR5"] = "Mẹ tôi rất mệt mỏi, tôi không muốn ra ngoài?",
	["COMIC_22_4_KR5_KR5"] = "Nhanh chóng trở về để thông báo cho Vua và Vez'nan.",
	["COMIC_22_5_KR5_KR5"] = "Bây giờ có thể thu hồi trứng của Nữ hoàng!",
	["COMIC_23_1_KR5_KR5"] = "Chúng tôi đã làm!",
	["COMIC_23_2_KR5_KR5"] = "Nữ hoàng đã được tái chế!",
	["COMIC_2_10_KR6_KR6"] = "Chỉ cần nhìn thấy điều này, các đồng minh trên khắp vương quốc sẽ giúp bạn.",
	["COMIC_2_11_KR6_KR6"] = "Cảm ơn anh, vua vĩ đại.",
	["COMIC_2_12_KR6_KR6"] = "Tin tức trực tiếp cho Denas.",
	["COMIC_2_1_1_KR2"] = "Bạn có chắc chắn rằng dòng sông này ở gần đây không?",
	["COMIC_2_1_2_KR2"] = "Có",
	["COMIC_2_1_KR3"] = "Sau đó, khi quân tinh linh bị vây trong Rừng Tiên…",
	["COMIC_2_1_KR5"] = "Chúc mừng!",
	["COMIC_2_1_KR6_KR6"] = "Cảm ơn anh, anh đã giúp đỡ! Làm sao để trả tiền cho bạn?",
	["COMIC_2_2_1_KR2"] = "Chúng ta nhanh đi. Tôi muốn trở về trại.",
	["COMIC_2_2_1_KR3"] = "…công chúa tinh linh đến vương quốc Linirea cầu viện…",
	["COMIC_2_2_2_KR2"] = "Nhanh gì?",
	["COMIC_2_2_2_KR3"] = "Ta tìm chỗ an toàn thôi!",
	["COMIC_2_2_KR6_KR6"] = "Xin hãy lắng nghe lời của tôi!",
	["COMIC_2_3_KR2"] = "Đây là khu vực an toàn!",
	["COMIC_2_3_KR3"] = "Nhìn kìa! Một điện thờ!",
	["COMIC_2_3_KR5"] = "Vương Nam?!",
	["COMIC_2_3_KR6_KR6"] = "Tôi đã có nhiệm vụ trở lại từ tương lai đến thời điểm này. Ở thế giới tôi đã trải qua, Vez'nan không chỉ không phá hủy những viên ngọc mà còn bị thu hút bởi sức mạnh của nó, một lần nữa và một lần nữa, nó được coi là một viên ngọc.",
	["COMIC_2_4_1_KR3"] = "Những cổ ngữ Druid này sẽ bảo vệ nơi đây.",
	["COMIC_2_4_2_KR3"] = "Khoan đã…",
	["COMIC_2_4_KR6_KR6"] = "Cuối cùng, anh ta cũng bị phá hủy hoàn toàn bởi những ý tưởng ác trong đá quý. Mặc dù chúng ta đang đấu tranh chống lại, chúng ta vẫn không thể ngăn chặn sự hủy diệt của Vương quốc dưới sức mạnh của Ngài.",
	["COMIC_2_4a_KR5"] = "Rất chậm, tôi sẽ đề xuất.",
	["COMIC_2_4b_KR5"] = "Một giao dịch.",
	["COMIC_2_5_KR3"] = "Đây không phải cổ ngữ Druid… mà là…",
	["COMIC_2_5_KR5"] = "Sau khi làm gì với vương quốc?!",
	["COMIC_2_5_KR6_KR6"] = "Thậm chí cả con trai của ông, “Vua của Denas” sau đó cũng đã chết trong cuộc nổi dậy này.",
	["COMIC_2_6_KR3"] = "Tinh linh Chạng vạng!",
	["COMIC_2_6_KR5"] = "Vua Denas cần nhận ra thực tế.",
	["COMIC_2_6_KR6_KR6"] = "Vì thế, ông đã bổ nhiệm tôi trở lại thời đại này, ngăn chặn sự cố xảy ra.",
	["COMIC_2_7_KR5"] = "Từ đó đến nay, ông ta đã không nhìn thấy nguy hiểm của vương quốc.",
	["COMIC_2_7_KR6_KR6"] = "Đây không phải là câu chuyện mà hai từ có thể tin được.",
	["COMIC_2_8_1_KR5"] = "Hãy cùng tìm lại vua của bạn.",
	["COMIC_2_8_2_KR5"] = "Và cùng nhau kết thúc cuộc khủng hoảng này.",
	["COMIC_2_8_KR6_KR6"] = "Tuy nhiên, tên của bạn là “người sáng”.",
	["COMIC_2_8b_KR5"] = ". cùng hợp tác.",
	["COMIC_2_9_KR6_KR6"] = "- Thưa ông, hãy mang theo cái bút này.",
	["COMIC_3_1_KR2"] = "Nơi này khiến tôi sợ hãi.",
	["COMIC_3_1_KR3"] = "Quân tinh linh theo dấu Malicia vào phế tích cổ của Thành phố Đầu tiên…",
	["COMIC_3_1_KR5"] = "Thiên Chúa! Đây là gì?",
	["COMIC_3_1_KR6_KR6"] = "Đêm đó -",
	["COMIC_3_2_1_KR3"] = "Ta nhất định sẽ báo thù!",
	["COMIC_3_2_2_KR3"] = "Suỵt… cưng à!",
	["COMIC_3_2_KR2"] = "Sắt và lửa! Tất cả những gì bạn cần để đánh bại kẻ địch!",
	["COMIC_3_2_KR5"] = "Thánh kiếm Elynie!",
	["COMIC_3_2_KR6_KR6"] = "Đi ra đi, rác!",
	["COMIC_3_3_KR2"] = "Nếu bạn nói như vậy.",
	["COMIC_3_3_KR3"] = "Đi thôi! Bắt ả ngay!",
	["COMIC_3_3_KR5"] = "Oh ơi!",
	["COMIC_3_3_KR6_KR6"] = "Đây là đất của con thú!",
	["COMIC_3_4_KR6_KR6"] = "- Thưa Thầy, Thầy muốn xem có mấy cái gì!",
	["COMIC_3_4a_KR5"] = "Tất nhiên.",
	["COMIC_3_4b_KR5"] = "Ngươi tỉnh!",
	["COMIC_3_5_1_KR3"] = "Đây là…",
	["COMIC_3_5_2_KR3"] = "…một cái bẫy!",
	["COMIC_3_5_KR6_KR6"] = "Chủ nhân.",
	["COMIC_3_5a_KR5"] = "- Thật ra, anh ta gần hơn anh ta nghĩ.",
	["COMIC_3_5b_KR5"] = "Vua của chúng ta vẫn còn không rõ.",
	["COMIC_3_6_1_KR3"] = "Anh em… chúng ta có khách.",
	["COMIC_3_6_2_KR3"] = "Đúng vậy!",
	["COMIC_3_6_KR5"] = "Tuy nhiên, đây có thể là một trận chiến khó khăn.",
	["COMIC_3_6_KR6_KR6"] = "Không có gì đáng tranh cãi, bạn bè.",
	["COMIC_3_7_KR3"] = "Nơi này giờ là chốn trú ẩn của bóng tối!",
	["COMIC_3_7_KR6_KR6"] = "Chỉ cần có sức mạnh của tôi, cộng với sự giúp đỡ của bạn, bạn có thể nhận được bao nhiêu đất mà bạn muốn.",
	["COMIC_3_8_KR6_KR6"] = "Tại sao chúng ta phải nghe người con người này nói ngu ngốc?",
	["COMIC_3_9_KR6_KR6"] = "Đó là tốt.",
	["COMIC_4_10a_KR5"] = "Hạ! Tôi luôn luôn.",
	["COMIC_4_10b_KR5"] = "Vậy. bây giờ làm gì?",
	["COMIC_4_11_KR5"] = "Có thể có sự khác biệt.",
	["COMIC_4_12_KR5"] = "Tuy nhiên, chúng ta có mối đe dọa lớn hơn.",
	["COMIC_4_1_1_KR3"] = "Trong lúc đó, tại đền nữ thần…",
