	["ENEMY_BLUE_WYVERN_NAME"] = "Blue Wyvern",
	["ENEMY_BLUE_WYVERN_NOTIFICATION_DESCRIPTION"] = "Được sinh ra từ Jokull, chúng bay nhanh qua phòng tuyến để tìm con mồi dễ săn.",
	["ENEMY_BOATSWAIN_ENCYC_SPECIAL"] = "Sát thương cận chiến diện rộng",
	["ENEMY_BOATSWAIN_EXTRA"] = "- Sát thương cận chiến diện rộng",
	["ENEMY_BOATSWAIN_NAME"] = "Boatswain",
	["ENEMY_BOATSWAIN_NOTIFICATION_DESCRIPTION"] = "Thủy thủ dày dạn chiến trận, giữ vững vị trí và làm chủ tình hình trên chiến trường.",
	["ENEMY_BOLGUR_BATTLE_TAUNT_1"] = "Tôi muốn đầu tư nhiều hơn cho quân đội.",
	["ENEMY_BOLGUR_BATTLE_TAUNT_2"] = "Bạn phải trả giá cho thất bại của mình. Tôi nói giá thật!",
	["ENEMY_BOLGUR_BATTLE_TAUNT_3"] = "Chơi đẹp! Muốn uống bia?",
	["ENEMY_BOLGUR_BATTLE_TAUNT_4"] = "Tôi không ghét những con quái vật.",
	["ENEMY_BOLGUR_BATTLE_TAUNT_5"] = "Hãy nói với tôi giá của bạn là bao nhiêu?",
	["ENEMY_BOLGUR_BATTLE_TAUNT_6"] = "Có được! Bạn có biết giá bao nhiêu là để làm sạch nơi này?",
	["ENEMY_BOLGUR_BATTLE_TAUNT_7"] = "Con vật không bao giờ yêu mến người chủ trả tiền.",
	["ENEMY_BOLGUR_INTRO_TAUNT_1"] = "Tôi sẽ viết bài hát để nhớ lại chiến thắng này!",
	["ENEMY_BOLGUR_INTRO_TAUNT_2"] = "Không phải tôi viết, mà là những người viết bài thơ của tôi.",
	["ENEMY_BOMBER_PARROT_ENCYC_SPECIAL"] = "Tăng tốc sau khi ném bom.",
	["ENEMY_BOMBER_PARROT_EXTRA"] = "- Tăng tốc sau khi ném bom.",
	["ENEMY_BOMBER_PARROT_NAME"] = "Bomber Parrot",
	["ENEMY_BOMBER_PARROT_NOTIFICATION_DESCRIPTION"] = "Những kẻ phá rối biết bay luôn gây rắc rối và có niềm say mê kỳ lạ với chất nổ.",
	["ENEMY_BONES_CARRIER_ENCYC_SPECIAL"] = "Tăng sát thương và hồi máu khi đồng minh chết",
	["ENEMY_BONE_CARRIER_EXTRA"] = "- Tăng sát thương\n- Hồi máu khi đồng minh chết",
	["ENEMY_BONE_CARRIER_NAME"] = "Bone Carrier",
	["ENEMY_BONE_CARRIER_NOTIFICATION_DESCRIPTION"] = "Quái vật khổng lồ làm từ xương, trừng phạt mọi thứ và không bao giờ nghỉ ngơi.",
	["ENEMY_BOOMSHROOMS_DESCRIPTION"] = "Một loại nấm rất bất ổn, khi bị đe dọa sẽ nổ.",
	["ENEMY_BOOMSHROOMS_EXTRA"] = "- nhanh chóng\n- Bão bão",
	["ENEMY_BOOMSHROOMS_NAME"] = "Boomshroom",
	["ENEMY_BOOMSHROOMS_SPECIAL"] = "Bão bão",
	["ENEMY_BOOM_BABOON_ENCYC_SPECIAL"] = "Sát thương diện rộng, Phát nổ khi tiếp xúc, Xuất hiện một con khỉ sau vụ nổ",
	["ENEMY_BOOM_BABOON_EXTRA"] = "- Sát thương diện rộng\n- Phát nổ khi tiếp xúc\n- Xuất hiện một con khỉ sau vụ nổ",
	["ENEMY_BOOM_BABOON_NAME"] = "Boom Baboon",
	["ENEMY_BOOM_BABOON_NOTIFICATION_DESCRIPTION"] = "Biết tinh tinh không được mang súng máy, lũ khỉ này chuyển sang vũ khí dự phòng: thùng thuốc nổ.",
	["ENEMY_BORON_ALCHEMIST_DESCRIPTION"] = "Những nhà giả kim tài ba dùng thuốc để khiến đồng minh cuồng nộ và đóng băng kẻ thù.",
	["ENEMY_BORON_ALCHEMIST_ENCYC_SPECIAL"] = "Ném thuốc cuồng nộ cho đồng minh và thuốc đóng băng vào kẻ địch",
	["ENEMY_BORON_ALCHEMIST_NAME"] = "Boron Alchemist",
	["ENEMY_BORON_ALCHEMIST_NOTIFICATION_BOTTOM"] = "- Ném thuốc cuồng nộ và đóng băng\n- Giáp vật lý cao",
	["ENEMY_BORON_ALCHEMIST_NOTIFICATION_DESCRIPTION"] = "Những nhà giả kim tài ba dùng thuốc để khiến đồng minh cuồng nộ và đóng băng kẻ thù.",
	["ENEMY_BORON_ALCHEMIST_NOTIFICATION_TITLE"] = "Boron Alchemist",
	["ENEMY_BORON_ALCHEMIST_SPECIAL"] = "Ném thuốc cuồng nộ cho đồng minh và thuốc đóng băng vào kẻ địch",
	["ENEMY_BOSS_ANCIENT_GHOST_ENCYC_DESCRIPTION"] = "Hai anh em ma quái đến đòi tiền công từ kẻ từng mượn quân đội và sức mạnh của chúng, kèm một khoản lãi khổng lồ.",
	["ENEMY_BOSS_ANCIENT_GHOST_ENCYC_NAME"] = "Ancient Ghost",
	["ENEMY_BOSS_ANCIENT_GHOST_ENCYC_SPECIAL"] = "Trùm, không thể bị chặn",
	["ENEMY_BOSS_BAJNIMEN_DESCRIPTION"] = "Có người nói rằng anh ta bị bệnh tật, những người này thường mất tích mà không có lý do, chỉ để lại một bãi cỏ.",
	["ENEMY_BOSS_BAJNIMEN_NAME"] = "Baj'Nimen the Hateful",
	["ENEMY_BOSS_BAJNIMEN_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_BALROG_DESCRIPTION"] = "Lời khuyên của người anh em, người anh em của mình, là “người ghen tị”.",
	["ENEMY_BOSS_BALROG_NAME"] = "Godieth",
	["ENEMY_BOSS_BALROG_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_BANDIT_DESCRIPTION"] = "Các kẻ hủy diệt bề mặt nhất và khát nhất của Vương quốc. Không có nghi ngờ gì, anh ta sẽ cố gắng lấy tiền của bạn!",
	["ENEMY_BOSS_BANDIT_NAME"] = "The Kingpin",
	["ENEMY_BOSS_BANDIT_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_BLACKBURN_DESCRIPTION"] = "Một người thợ săn vĩ đại và quý giá, vì quá khát khao khát để trừng phạt, thay vào đó đã phá hủy bản thân và lục địa của mình.",
	["ENEMY_BOSS_BLACKBURN_NAME"] = "Lord Blackburn",
	["ENEMY_BOSS_BLACKBURN_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_BOLGUR_ENCYC_DESCRIPTION"] = "Vua của người lùn, có tài sản khổng lồ và trí tuệ hơn người, xứng đáng làm kẻ cai trị. Bolgur còn lái một cỗ mecha khổng lồ.",
	["ENEMY_BOSS_BOLGUR_ENCYC_NAME"] = "Bolgur the Golden King",
	["ENEMY_BOSS_BOLGUR_ENCYC_SPECIAL"] = "Trùm, tấn công tầm xa",
	["ENEMY_BOSS_BRAM_DESCRIPTION"] = "Lãnh đạo ăn thịt tàn bạo, thích làm việc theo cách cắt đứt.",
	["ENEMY_BOSS_BRAM_NAME"] = "Bram, the Beheader",
	["ENEMY_BOSS_BRAM_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_BULL_KING_DESCRIPTION"] = "Ngưu Ma Vương tự xưng Bình Thiên Đại Thánh, từng kết nghĩa với Tôn Ngộ Không. Hắn là chồng của Thiết Phiến Công Chúa và sở hữu sức mạnh lay chuyển núi đồi.",
	["ENEMY_BOSS_BULL_KING_NAME"] = "Bull Demon King",
	["ENEMY_BOSS_CORRUPTED_DENAS_DESCRIPTION"] = "Vua Linirea bị đánh bại rồi tha hóa bởi sức mạnh hắc ám của Overseer, biến thành một quái vật đáng sợ.",
	["ENEMY_BOSS_CORRUPTED_DENAS_NAME"] = "Corrupted Denas",
	["ENEMY_BOSS_CROCS_2_NAME"] = "Abominor Venomus",
	["ENEMY_BOSS_CROCS_3_NAME"] = "Abominor Ignis",
	["ENEMY_BOSS_CROCS_DESCRIPTION"] = "Hiện thân của cơn đói. Nếu để sinh vật cổ đại này tự do hành động, nó sẽ nuốt chửng cả thế giới.",
	["ENEMY_BOSS_CROCS_NAME"] = "Abominor",
	["ENEMY_BOSS_CULT_LEADER_DESCRIPTION"] = "Giáo chủ của giáo phái hắc ám, trợ thủ của Overseer. Hắn lập kế hoạch xâm lược những thế giới khác.",
	["ENEMY_BOSS_CULT_LEADER_NAME"] = "Seeress Mydrias",
	["ENEMY_BOSS_DEFORMED_GRYMBEARD_NAME"] = "Deformed Grymbeard",
	["ENEMY_BOSS_DRAGON_KING_ENCYC_DESCRIPTION"] = "Long Vương tỉnh giấc sau nhiều năm, chỉ để hủy diệt mọi kẻ cản đường.",
	["ENEMY_BOSS_DRAGON_KING_ENCYC_NAME"] = "Dragon King",
	["ENEMY_BOSS_DRAGON_KING_ENCYC_SPECIAL"] = "Trùm, không thể bị chặn",
	["ENEMY_BOSS_DRAGON_STAGE_39_DESCRIPTION"] = "Con rồng bị tha hóa có máu độc làm ô nhiễm đất đai và nuôi dưỡng đàn rồng con phục vụ chủ nhân Tyransol.",
	["ENEMY_BOSS_DRAGON_STAGE_39_NAME"] = "Mẹ của ma quỷ",
	["ENEMY_BOSS_DRAGON_STAGE_40_DESCRIPTION"] = "Con ác long đầy tham vọng muốn chiếm đoạt Vân Quốc. Hắn vừa xảo quyệt vừa tàn bạo. Khi hệ số máu của boss vượt 1.1, đòn đánh chuyển sang gây sát thương theo tỷ lệ thay cho mức cố định.",
	["ENEMY_BOSS_DRAGON_STAGE_40_NAME"] = "Tiểu Thinh",
	["ENEMY_BOSS_DROW_QUEEN_DESCRIPTION"] = "Nữ hoàng ác và chết người, ba lần đánh bại trong cuộc đua Scorpio.",
	["ENEMY_BOSS_DROW_QUEEN_NAME"] = "Malicia",
	["ENEMY_BOSS_DROW_QUEEN_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_DROW_QUEEN_ZEALOT_NAME"] = "Zealot",
	["ENEMY_BOSS_DWARF_MECHA_NAME"] = "Bolgur the Golden King",
	["ENEMY_BOSS_GNOLL_DESCRIPTION"] = "Kẻ độc ác nhất và hôi hám nhất trong bộ tộc Gnoll. Hắn tức giận vì chưa từng được mời đến dự tiệc.",
	["ENEMY_BOSS_GNOLL_NAME"] = "Hi-Hi Enha",
	["ENEMY_BOSS_GNOLL_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_GOBLIN_CHIEFTAIN_DESCRIPTION"] = "Động vật đáng sợ nhất. Cũng khôn khiếp trong cuộc chiến, chỉ có câu chuyện chiến đấu chán ngập của anh ta mới có thể phù hợp.",
	["ENEMY_BOSS_GOBLIN_CHIEFTAIN_EXTRA"] = "Trùm",
	["ENEMY_BOSS_GOBLIN_CHIEFTAIN_NAME"] = "Gul'Thak",
	["ENEMY_BOSS_GOBLIN_CHIEFTAIN_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_GREAT_T_ENCYC_DESCRIPTION"] = "Bá chủ đầu tiên, nỗi kinh hoàng của thế giới đã mất, hiện thân của hiểm ác và cơn đói… May cho kẻ địch, Great-T thích ngủ hơn ăn.",
	["ENEMY_BOSS_GREAT_T_ENCYC_NAME"] = "Great-T",
	["ENEMY_BOSS_GREAT_T_ENCYC_SPECIAL"] = "Trùm, tấn công tầm xa, hạ gục tức thì, hồi máu khi ăn",
	["ENEMY_BOSS_GRYMBEARD_DESCRIPTION"] = "Thủ lĩnh của đội quân thép hắc ám.",
	["ENEMY_BOSS_GRYMBEARD_NAME"] = "Grymbeard",
	["ENEMY_BOSS_JOKULL_ENCYC_DESCRIPTION"] = "Mẹ của loài wyvern, lò lửa của núi. Jokull có thân hình khổng lồ và sức mạnh cũng vô biên.",
	["ENEMY_BOSS_JOKULL_ENCYC_NAME"] = "Jokull",
	["ENEMY_BOSS_JOKULL_ENCYC_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_MACHINIST_DESCRIPTION"] = "Trò chơi đeo trên những phát minh mới nhất của họ để theo đuổi kẻ địch, hạ xuống lửa và kim loại mưa.",
	["ENEMY_BOSS_MACHINIST_NAME"] = "Grymbeard",
	["ENEMY_BOSS_MURGLUM_DESCRIPTION"] = "Con rồng dung nham cái mạnh mẽ nhất từng được biết đến. Từng bị Vez'nan điều khiển, Murglun nay đã tự do và tự nguyện theo chủ mới. Cô là một tai họa rực lửa, với cơn giận gần như không thể dập tắt.",
	["ENEMY_BOSS_MURGLUM_EXTRA"] = "- Đổ bóng lửa trên đường\n- Tháp phòng thủ bị chặn\n- Đánh bại đơn vị, gây sát thương diện rộng",
	["ENEMY_BOSS_MURGLUM_NAME"] = "Murglun",
	["ENEMY_BOSS_NAVIRA_DESCRIPTION"] = "Navira đã nhiễm sức mạnh cấm kỵ và đánh mất ân sủng của nữ thần. Hắn dùng ma thuật chết chóc để khôi phục vinh quang của tộc tinh linh.",
	["ENEMY_BOSS_NAVIRA_NAME"] = "Navira",
	["ENEMY_BOSS_OVERSEER_DESCRIPTION"] = "Thực thể được gọi là Con Mắt Toàn Tri, xâm nhập các chiều không gian để thôn tính thế giới và hấp thụ năng lượng. Phải ngăn chặn nó bằng mọi giá!",
	["ENEMY_BOSS_OVERSEER_NAME"] = "The Overseer",
	["ENEMY_BOSS_PIG_DESCRIPTION"] = "Tự xưng là đỉnh cao của muôn loài, hắn có thể biến thành một con thú khổng lồ.",
	["ENEMY_BOSS_PIG_NAME"] = "Goregrind",
	["ENEMY_BOSS_POLYX_ENCYC_DESCRIPTION"] = "Anurian thông thái nhất. Thân hình quá đồ sộ khiến Polyx chỉ có thể di chuyển bằng ma lực vô song. Cẩn thận kẻo bị hắn nuốt chửng.",
	["ENEMY_BOSS_POLYX_ENCYC_NAME"] = "Polyx the Wise",
	["ENEMY_BOSS_POLYX_ENCYC_SPECIAL"] = "Trùm, hạ gục tức thì, dịch chuyển",
	["ENEMY_BOSS_PRINCESS_IRON_FAN_CLONE_NAME"] = "Princess Iron Fan Clone",
	["ENEMY_BOSS_PRINCESS_IRON_FAN_DESCRIPTION"] = "Thiết Phiến Công Chúa sở hữu quạt Ba Tiêu, có thể gọi gió, tạo mưa và dập tắt lửa. Bảo vật ấy khiến cả thần lẫn yêu quái phải kiêng dè.",
	["ENEMY_BOSS_PRINCESS_IRON_FAN_NAME"] = "Princess Iron Fan",
	["ENEMY_BOSS_REDBOY_TEEN_DESCRIPTION"] = "Hồng Hài Nhi, con trai Ngưu Ma Vương và Thiết Phiến Công Chúa, đã tu luyện Tam Muội Chân Hỏa suốt ba trăm năm. Hắn thiện dùng thương và thường ức hiếp sơn thần quanh vùng.",
	["ENEMY_BOSS_REDBOY_TEEN_NAME"] = "Red Boy",
	["ENEMY_BOSS_SPIDER_DEATH_TAUNT"] = "Không thể!",
	["ENEMY_BOSS_SPIDER_DESCRIPTION"] = "Một điều ghê tởm. khi chơi các tác phẩm nghệ thuật tinh thần là như vậy.",
	["ENEMY_BOSS_SPIDER_NAME"] = "Spider Goddess",
	["ENEMY_BOSS_SPIDER_QUEEN_DESCRIPTION"] = "Nữ hoàng nhện cổ đại thức tỉnh sau giấc ngủ dài, quyết giành lại mọi thứ từng thuộc về mình.",
	["ENEMY_BOSS_SPIDER_QUEEN_NAME"] = "Mygale",
	["ENEMY_BOSS_SPIDER_SPECIAL"] = "Trùm",
	["ENEMY_BOSS_STAGE_08_DESCRIPTION"] = "Tên thủ lĩnh da xanh hung bạo, có sức mạnh đủ phá vỡ tường thành. Hãy cẩn thận khi đối đầu với hắn.",
	["ENEMY_BOSS_STAGE_08_EXTRA"] = "",
	["ENEMY_BOSS_STAGE_08_NAME"] = "Gor’Thok",
	["ENEMY_BOSS_STAGE_08_SPECIAL"] = "",
	["ENEMY_BOSS_STAGE_10_DESCRIPTION"] = "Một quái vật ghê tởm sống trên núi, dường như vừa bị chúng ta vô tình đánh thức khỏi giấc ngủ.",
	["ENEMY_BOSS_STAGE_10_EXTRA"] = "- Đơn vị ăn\n- Đóng băng tháp phòng thủ",
	["ENEMY_BOSS_STAGE_10_NAME"] = "J.T.",
	["ENEMY_BOSS_STAGE_11_DESCRIPTION"] = "Nữ hoàng Nhện phương Bắc là đối thủ chết chóc, đủ sức một mình san phẳng cả doanh trại.",
