	["HERO_ELVES_PIXIE_ATTACKRATE"] = "Trung bình",
	["HERO_ELVES_PIXIE_CLASS"] = "Tinh thần hùng",
	["HERO_ELVES_PIXIE_CURSE_DESCRIPTION_1"] = "Mỗi đòn đánh của tiên nhỏ có 20% cơ hội nguyền rủa kẻ địch, làm choáng trong 0.5 giây.",
	["HERO_ELVES_PIXIE_CURSE_DESCRIPTION_2"] = "Mỗi đòn đánh của tiên nhỏ có 20% cơ hội nguyền rủa kẻ địch, làm choáng trong 1 giây.",
	["HERO_ELVES_PIXIE_CURSE_DESCRIPTION_3"] = "Mỗi đòn đánh của tiên nhỏ có 20% cơ hội nguyền rủa kẻ địch, làm choáng trong 1.5 giây.",
	["HERO_ELVES_PIXIE_CURSE_TITLE"] = "Pixie's Curse",
	["HERO_ELVES_PIXIE_DESCRIPTION"] = "Các tiên nhỏ thường rụt rè, ca hát và nhảy múa dưới những cây sồi cổ. Catha cũng hay cười, nhưng cô không hề yếu đuối. Kiên cường và quả cảm, cô bước theo dấu chân chiến binh tiên vĩ đại Sunha. Catha hồi máu cho đồng minh, ném gai phép vào kẻ địch và ru chúng ngủ. Bụi tiên còn giúp cô tạo ra các phân thân khiến quân địch khiếp sợ!",
	["HERO_ELVES_PIXIE_DUST_DESCRIPTION_1"] = "Thi triển phép chớp nhoáng, làm choáng mọi kẻ địch trong một vùng trong 3 giây.",
	["HERO_ELVES_PIXIE_DUST_DESCRIPTION_2"] = "Thi triển phép chớp nhoáng, làm choáng mọi kẻ địch trong một vùng trong 4.5 giây.",
	["HERO_ELVES_PIXIE_DUST_DESCRIPTION_3"] = "Thi triển phép chớp nhoáng, làm choáng mọi kẻ địch trong một vùng trong 6 giây.",
	["HERO_ELVES_PIXIE_DUST_MENUBOTTOM_DESCRIPTION"] = "Đưa kẻ địch vào giấc ngủ.",
	["HERO_ELVES_PIXIE_DUST_MENUBOTTOM_NAME"] = "Faery Dust",
	["HERO_ELVES_PIXIE_DUST_TITLE"] = "Faery Dust",
	["HERO_ELVES_PIXIE_FURY_DESCRIPTION_1"] = "Cử 2 tiên nhỏ tấn công kẻ địch gần đó, mỗi tiên gây 10–30 sát thương phép.",
	["HERO_ELVES_PIXIE_FURY_DESCRIPTION_2"] = "Cử 3 tiên nhỏ tấn công kẻ địch gần đó, mỗi tiên gây 12–40 sát thương phép.",
	["HERO_ELVES_PIXIE_FURY_DESCRIPTION_3"] = "Cử 4 tiên nhỏ tấn công kẻ địch gần đó, mỗi tiên gây 18–50 sát thương phép.",
	["HERO_ELVES_PIXIE_FURY_TITLE"] = "Pixie's Fury",
	["HERO_ELVES_PIXIE_NAME"] = "Catha",
	["HERO_ELVES_PIXIE_SHADOW_NAME"] = "Pixie Warrior",
	["HERO_ELVES_PIXIE_SOUL_DESCRIPTION_1"] = "Bùng nổ tiên thuật, hồi 50 máu cho tối đa 3 đồng minh.",
	["HERO_ELVES_PIXIE_SOUL_DESCRIPTION_2"] = "Bùng nổ tiên thuật, hồi 100 máu cho tối đa 3 đồng minh.",
	["HERO_ELVES_PIXIE_SOUL_DESCRIPTION_3"] = "Bùng nổ tiên thuật, hồi 150 máu cho tối đa 3 đồng minh.",
	["HERO_ELVES_PIXIE_SOUL_TITLE"] = "Faery Soul",
	["HERO_ELVES_PIXIE_SPEED"] = "Trung bình",
	["HERO_ELVES_PIXIE_TALE_DESCRIPTION_1"] = "Lời kêu 2 Một chiến binh khỉ, ngăn chặn và tấn công kẻ địch.",
	["HERO_ELVES_PIXIE_TALE_DESCRIPTION_2"] = "3 chiến binh đếch có máu động, ngăn chặn và tấn công kẻ địch.",
	["HERO_ELVES_PIXIE_TALE_DESCRIPTION_3"] = "4 chiến binh đếch có máu động, ngăn chặn và tấn công kẻ địch.",
	["HERO_ELVES_PIXIE_TALE_TITLE"] = "Faery Tale",
	["HERO_ELVES_RAG_ANGRY_GNOME_DESCRIPTION_1"] = "Razz dùng phép tạo một vật ngẫu nhiên rồi ném đi, gây 25–45 sát thương.",
	["HERO_ELVES_RAG_ANGRY_GNOME_DESCRIPTION_2"] = "Razz dùng phép tạo một vật ngẫu nhiên rồi ném đi, gây 50–90 sát thương.",
	["HERO_ELVES_RAG_ANGRY_GNOME_DESCRIPTION_3"] = "Razz dùng phép tạo một vật ngẫu nhiên rồi ném đi, gây 75–135 sát thương.",
	["HERO_ELVES_RAG_ANGRY_GNOME_TITLE"] = "Angry Gnome",
	["HERO_ELVES_RAG_ATTACKRATE"] = "Trung bình",
	["HERO_ELVES_RAG_CLASS"] = "Rick",
	["HERO_ELVES_RAG_DESCRIPTION"] = "Điều gì xảy ra khi một người bé nhỏ bị dồn đến đường cùng? Khi tinh linh Chạng vạng phá nhà, ogre chiếm đất và gnoll giày xéo cuộc sống của các gnome hiền lành, một anh chàng quyết định chấm dứt tất cả. Cậu chế tạo một người bạn khổng lồ để giúp sức. Thế là bộ đôi kỳ lạ nhất trong hàng ngũ anh hùng xuất hiện: Razz & Rags!",
	["HERO_ELVES_RAG_HAMMER_TIME_DESCRIPTION_1"] = "Rags đấm xuống một vùng, làm choáng kẻ địch và gây 72 sát thương trong 3 giây.",
	["HERO_ELVES_RAG_HAMMER_TIME_DESCRIPTION_2"] = "Rags đấm xuống một vùng, làm choáng kẻ địch và gây 96 sát thương trong 4 giây.",
	["HERO_ELVES_RAG_HAMMER_TIME_DESCRIPTION_3"] = "Rags đấm xuống một vùng, làm choáng kẻ địch và gây 120 sát thương trong 5 giây.",
	["HERO_ELVES_RAG_HAMMER_TIME_TITLE"] = "Hammer Time",
