	["HERO_ILLIANA_SKILL_A_2_TITLE"] = "TAG! II",
	["HERO_ILLIANA_SKILL_A_3_DESCRIPTION"] = "Sparky phun lửa nảy tối đa {b.heroes.hero_illiana.skill_a.max_bounces} lần, gây {b.heroes.hero_illiana.upgrades.upg_sa2.damage_min}–{b.heroes.hero_illiana.upgrades.upg_sa2.damage_max} sát thương chuẩn và giảm {b.heroes.hero_illiana.skill_a.armor_red}% giáp của mục tiêu.",
	["HERO_ILLIANA_SKILL_A_3_TITLE"] = "TAG! III",
	["HERO_ILLIANA_SKILL_B_1_DESCRIPTION"] = "Bắn một quả bom phát nổ, làm choáng kẻ địch trong {b.heroes.hero_illiana.skill_b.stun_duration} giây.",
	["HERO_ILLIANA_SKILL_B_1_TITLE"] = "GLITTER BOMB I",
	["HERO_ILLIANA_SKILL_B_2_DESCRIPTION"] = "Bắn một quả bom phát nổ, làm choáng kẻ địch trong {b.heroes.hero_illiana.upgrades.upg_sb1.stun_duration} giây.",
	["HERO_ILLIANA_SKILL_B_2_TITLE"] = "GLITTER BOMB II",
	["HERO_ILLIANA_SKILL_B_3_DESCRIPTION"] = "Bắn một quả bom phát nổ, làm choáng kẻ địch trong {b.heroes.hero_illiana.upgrades.upg_sb2.stun_duration} giây.",
	["HERO_ILLIANA_SKILL_B_3_TITLE"] = "GLITTER BOMB III",
	["HERO_ILLIANA_SKILL_C_1_DESCRIPTION"] = "Sparky lao vào một kẻ địch đang bị choáng, gây {b.heroes.hero_illiana.skill_c.damage_min}–{b.heroes.hero_illiana.skill_c.damage_max} sát thương vật lý.",
	["HERO_ILLIANA_SKILL_C_1_TITLE"] = "EASY PREY I",
