	["HERO_MALIK_G6_SKILL_A_2_TITLE"] = "UNBREAKABLE II",
	["HERO_MALIK_G6_SKILL_A_3_DESCRIPTION"] = "Tạo khiên bằng {b.heroes.hero_malik.upgrades.upg_sa2.hp_increase_ptg}% máu của kẻ địch Malik đang chặn, kéo dài {b.heroes.hero_malik.skill_a.duration} giây.",
	["HERO_MALIK_G6_SKILL_A_3_TITLE"] = "UNBREAKABLE III",
	["HERO_MALIK_G6_SKILL_B_1_DESCRIPTION"] = "Nhảy lên nện đất, gây {b.heroes.hero_malik.skill_b.damage_min}–{b.heroes.hero_malik.skill_b.damage_max} sát thương vật lý và làm choáng kẻ địch trong {b.heroes.hero_malik.skill_b.stun_duration} giây.",
	["HERO_MALIK_G6_SKILL_B_1_TITLE"] = "EARTHQUAKE I",
	["HERO_MALIK_G6_SKILL_B_2_DESCRIPTION"] = "Nhảy lên nện đất, gây {b.heroes.hero_malik.skill_b.damage_min}–{b.heroes.hero_malik.skill_b.damage_max} sát thương vật lý và làm choáng kẻ địch trong {b.heroes.hero_malik.upgrades.upg_sb1.stun_duration} giây.",
	["HERO_MALIK_G6_SKILL_B_2_TITLE"] = "EARTHQUAKE II",
	["HERO_MALIK_G6_SKILL_B_3_DESCRIPTION"] = "Nhảy lên nện đất trên phạm vi rộng hơn, gây {b.heroes.hero_malik.skill_b.damage_min}–{b.heroes.hero_malik.skill_b.damage_max} sát thương vật lý và làm choáng kẻ địch trong {b.heroes.hero_malik.upgrades.upg_sb1.stun_duration} giây.",
	["HERO_MALIK_G6_SKILL_B_3_TITLE"] = "EARTHQUAKE III",
	["HERO_MALIK_G6_SKILL_C_1_DESCRIPTION"] = "Gồng một lúc rồi vung búa, hất mục tiêu bay khỏi bản đồ.",
	["HERO_MALIK_G6_SKILL_C_1_TITLE"] = "OBLITERATE I",
	["HERO_MALIK_G6_SKILL_C_2_DESCRIPTION"] = "Gồng một lúc rồi vung búa, hất mục tiêu bay khỏi bản đồ. Giảm hồi chiêu còn {b.heroes.hero_malik.upgrades.upg_sc1.cooldown} giây.",
	["HERO_MALIK_G6_SKILL_C_2_TITLE"] = "OBLITERATE II",
	["HERO_MALIK_G6_SKILL_C_3_DESCRIPTION"] = "Gồng một lúc rồi vung búa, hất mục tiêu bay khỏi bản đồ. Giảm hồi chiêu còn {b.heroes.hero_malik.upgrades.upg_sc2.cooldown} giây.",
	["HERO_MALIK_G6_SKILL_C_3_TITLE"] = "OBLITERATE III",
