	["HERO_MALIK_G6_ULT_DESCRIPTION"] = "Xoay búa liên tục, gây {b.heroes.hero_malik.ultimate.s_total_min_damage}–{b.heroes.hero_malik.ultimate.s_total_max_damage} sát thương vật lý trong {b.heroes.hero_malik.ultimate.duration} giây và làm chậm kẻ địch gần đó.",
	["HERO_MALIK_G6_ULT_TITLE"] = "HAMMERNADO",
	["HERO_MALIK_SKILLS_INTRO"] = "Đã bị phá vỡ, động đất",
	["HERO_MAMMOTH_ATTACKRATE"] = "Trung bình",
	["HERO_MAMMOTH_CLASS"] = "Bạo chúa cổ đại",
	["HERO_MAMMOTH_DESCRIPTION"] = "Quân tử báo thù, mười năm chưa muộn. Grosh hiểu rõ điều đó. Hắn chờ năm này qua năm khác để trở về thế giới của mình và thực hiện kế hoạch trả thù. Cuối cùng cơ hội đã đến: tiêu diệt kẻ thù trước khi chúng kịp tiêu diệt hắn.",
	["HERO_MAMMOTH_FISSURE_2_TITLE"] = "Khe nứt II",
	["HERO_MAMMOTH_FISSURE_3_TITLE"] = "Khe nứt III",
	["HERO_MAMMOTH_FISSURE_DESCRIPTION_1"] = "Grosh gây 160 sát thương vật lý và làm choáng mục tiêu 1 giây, đồng thời khiến kẻ địch khác gần đó hoảng sợ trong 1.5 giây.",
	["HERO_MAMMOTH_FISSURE_DESCRIPTION_2"] = "Grosh gây 240 sát thương vật lý và làm choáng mục tiêu 1.5 giây, đồng thời khiến kẻ địch khác gần đó hoảng sợ trong 1.5 giây.",
	["HERO_MAMMOTH_FISSURE_DESCRIPTION_3"] = "Grosh gây 320 sát thương vật lý và làm choáng mục tiêu 2 giây, đồng thời khiến kẻ địch khác gần đó hoảng sợ trong 1.5 giây.",
	["HERO_MAMMOTH_FISSURE_TITLE"] = "Khe nứt",
	["HERO_MAMMOTH_FRENZY_2_TITLE"] = "Cuồng nộ II",
	["HERO_MAMMOTH_FRENZY_3_TITLE"] = "Cuồng nộ III",
	["HERO_MAMMOTH_FRENZY_DESCRIPTION_1"] = "Khi sắp nhận đòn chí tử, Grosh tránh cái chết và miễn sát thương trong 6 giây; thời gian giữa các đòn đánh giảm còn 0.88 giây.",
	["HERO_MAMMOTH_FRENZY_DESCRIPTION_2"] = "Khi sắp nhận đòn chí tử, Grosh tránh cái chết và miễn sát thương trong 7 giây; thời gian giữa các đòn đánh giảm còn 0.81 giây.",
	["HERO_MAMMOTH_FRENZY_DESCRIPTION_3"] = "Khi sắp nhận đòn chí tử, Grosh tránh cái chết và miễn sát thương trong 8 giây; thời gian giữa các đòn đánh giảm còn 0.75 giây.",
	["HERO_MAMMOTH_FRENZY_TITLE"] = "Cuồng nộ",
	["HERO_MAMMOTH_LEGACY_2_TITLE"] = "Di sản II",
	["HERO_MAMMOTH_LEGACY_3_TITLE"] = "Di sản III",
	["HERO_MAMMOTH_LEGACY_DESCRIPTION_1"] = "Khi Grosh chết, xương nhọn gây 30 sát thương vật lý mỗi giây và giảm 30% tốc độ di chuyển của kẻ địch gần đó cho đến khi Grosh hồi sinh.",
	["HERO_MAMMOTH_LEGACY_DESCRIPTION_2"] = "Khi Grosh chết, xương nhọn gây 40 sát thương vật lý mỗi giây và giảm 35% tốc độ di chuyển của kẻ địch gần đó cho đến khi Grosh hồi sinh.",
	["HERO_MAMMOTH_LEGACY_DESCRIPTION_3"] = "Khi Grosh chết, xương nhọn gây 50 sát thương vật lý mỗi giây và giảm 40% tốc độ di chuyển của kẻ địch gần đó cho đến khi Grosh hồi sinh.",
	["HERO_MAMMOTH_LEGACY_TITLE"] = "Di sản",
	["HERO_MAMMOTH_NAME"] = "Grosh",
	["HERO_MAMMOTH_PASSIVE_DESCRIPTION_1"] = "Khi không có đồng minh ở gần, Grosh nhận thêm 30% máu và sát thương.",
	["HERO_MAMMOTH_PASSIVE_TITLE"] = "Chiến binh đơn độc",
	["HERO_MAMMOTH_ULTIMATE_2_TITLE"] = "Nỗi sợ nguyên thủy II",
