	["HERO_MARGOSA_DARK_CALL_DESCRIPTION_1"] = "Dịch chuyển một kẻ địch đến trước mặt cô, ngăn nó tiến lên và làm choáng trong 2 giây.",
	["HERO_MARGOSA_DARK_CALL_DESCRIPTION_2"] = "Dịch chuyển một kẻ địch đến trước mặt cô, ngăn nó tiến lên và làm choáng trong 3 giây.",
	["HERO_MARGOSA_DARK_CALL_DESCRIPTION_3"] = "Dịch chuyển một kẻ địch đến trước mặt cô, ngăn nó tiến lên và làm choáng trong 4 giây.",
	["HERO_MARGOSA_DARK_CALL_TITLE"] = "Tiếng gọi bóng tối",
	["HERO_MARGOSA_DESCRIPTION"] = "Những vết thương trong thất bại của Lãnh chúa Vasile đã khắc sâu vào ký ức Margosa. Cô hồi phục trong một hang động biệt lập; sức mạnh và lòng căm thù Linirea đều ngày một lớn. Giờ cô trở lại chỉ để thỏa mãn cơn khát máu.",
	["HERO_MARGOSA_MYST_FORM_2_TITLE"] = "Sương mù tuyệt vọng II",
	["HERO_MARGOSA_MYST_FORM_3_TITLE"] = "Sương mù tuyệt vọng III",
	["HERO_MARGOSA_MYST_FORM_DESCRIPTION_1"] = "Bao bọc bản thân trong sương phép. Kẻ địch trong sương chịu 120 sát thương và có 25% cơ hội đánh trượt, kéo dài 5 giây.",
	["HERO_MARGOSA_MYST_FORM_DESCRIPTION_2"] = "Bao bọc bản thân trong sương phép. Kẻ địch trong sương chịu 180 sát thương và có 50% cơ hội đánh trượt, kéo dài 5 giây.",
	["HERO_MARGOSA_MYST_FORM_DESCRIPTION_3"] = "Bao bọc bản thân trong sương phép. Kẻ địch trong sương chịu 300 sát thương và có 75% cơ hội đánh trượt, kéo dài 5 giây.",
	["HERO_MARGOSA_MYST_FORM_TITLE"] = "Sương mù tuyệt vọng",
