	["HERO_ZEFIRA_SKILL_A_3_DESCRIPTION"] = "Nện búa năng lượng khổng lồ, gây {b.heroes.hero_zefira.upgrades.upg_sa2.min_damage}–{b.heroes.hero_zefira.upgrades.upg_sa2.max_damage} sát thương phép diện rộng và làm choáng mục tiêu trong {b.heroes.hero_zefira.skill_a.stun_duration} giây.",
	["HERO_ZEFIRA_SKILL_A_3_TITLE"] = "DAZZLING HAMMER III",
	["HERO_ZEFIRA_SKILL_B_1_DESCRIPTION"] = "Gọi kiếm năng lượng xoay quanh người, tăng {b.heroes.hero_zefira.skill_b.s_resistance_inc}% giáp vật lý và giáp phép, đồng thời gây {b.heroes.hero_zefira.skill_b.s_damage_total_lvl1} sát thương phép trong {b.heroes.hero_zefira.skill_b.duration} giây.",
	["HERO_ZEFIRA_SKILL_B_1_TITLE"] = "SHIELDING BLADES I",
	["HERO_ZEFIRA_SKILL_B_2_DESCRIPTION"] = "Gọi kiếm năng lượng xoay quanh người, tăng {b.heroes.hero_zefira.skill_b.s_resistance_inc}% giáp vật lý và giáp phép, gây {b.heroes.hero_zefira.skill_b.s_damage_total_lvl1} sát thương phép trong {b.heroes.hero_zefira.skill_b.duration} giây và làm chậm mục tiêu {b.heroes.hero_zefira.upgrades.upg_sb1.s_slow_factor}%.",
	["HERO_ZEFIRA_SKILL_B_2_TITLE"] = "SHIELDING BLADES II",
	["HERO_ZEFIRA_SKILL_B_3_DESCRIPTION"] = "Gọi kiếm năng lượng xoay quanh người, tăng {b.heroes.hero_zefira.skill_b.s_resistance_inc}% giáp vật lý và giáp phép, gây {b.heroes.hero_zefira.skill_b.s_damage_total_lvl1} sát thương phép trong {b.heroes.hero_zefira.upgrades.upg_sb2.duration} giây và làm chậm mục tiêu {b.heroes.hero_zefira.upgrades.upg_sb1.s_slow_factor}%.",
