	["LEVEL_SELECT_CHALLENGE_SIX_ELITE_WAVE"] = "6 đợt quân tinh nhuệ",
	["LEVEL_SELECT_CLICK_TO_SWAP"] = "Nhấn để thay thế",
	["LEVEL_SELECT_DIFFICULTY"] = "Độ khó",
	["LEVEL_SELECT_DIFFICULTY_CASUAL"] = "Casual",
	["LEVEL_SELECT_DIFFICULTY_IMPOSSIBLE"] = "Impossible",
	["LEVEL_SELECT_DIFFICULTY_NORMAL"] = "Normal",
