	["LEVEL_SELECT_GET_DLC"] = "Nhận ngay",
	["LEVEL_SELECT_HEROIC_TITLE"] = "Thử thách Anh hùng",
	["LEVEL_SELECT_HEROIC_WAVES"] = "6 đợt quân tinh nhuệ",
	["LEVEL_SELECT_IRON_TITLE"] = "Thử thách Sắt",
