	["LEVEL_SELECT_KR1_ONE_HERO"] = "Chỉ dùng một anh hùng",
	["LEVEL_SELECT_LIVES"] = "Chỉ có 1 máu",
	["LEVEL_SELECT_MODE_DIFFICULTY_1"] = "HARD",
	["LEVEL_SELECT_MODE_DIFFICULTY_2"] = "BRUTAL",
	["LEVEL_SELECT_MODE_DIFFICULTY_3"] = "EXTREME",
