	["SV_ACHIEVEMENT_ALIBABA_DESCRIPTION"] = "Tìm kiếm bằng sát thủ 10000 đồng vàng.",
	["SV_ACHIEVEMENT_ALIBABA_NAME"] = "Alibaba",
	["SV_ACHIEVEMENT_ANDSOITBEGINS_DESCRIPTION"] = "Hoàn thành đầu tiên.",
