	["SV_ACHIEVEMENT_COME_ON_YOU_APES_DESCRIPTION"] = "Đền ác đánh bại 30 kẻ địch tấn công.",
	["SV_ACHIEVEMENT_COME_ON_YOU_APES_NAME"] = "Nhìn nhỏ nhóc!",
	["SV_ACHIEVEMENT_DARING_DESCRIPTION"] = "Gọi sớm 10 đợt quái.",
	["SV_ACHIEVEMENT_DARING_NAME"] = "Một mình là can đảm",
	["SV_ACHIEVEMENT_DEADFROMBELOW_DESCRIPTION"] = "Đổ đầu ra 100 Hơn một kẻ địch.",
	["SV_ACHIEVEMENT_DEADFROMBELOW_NAME"] = "Cái chết dưới lòng đất",
	["SV_ACHIEVEMENT_DEAD_AND_LOVING_IT_DESCRIPTION"] = "Chiến thắng của hoàng tử Vasile.",
	["SV_ACHIEVEMENT_DEAD_AND_LOVING_IT_NAME"] = "Cái chết và tình yêu",
	["SV_ACHIEVEMENT_DEAD_PEOPLE_DESCRIPTION"] = "6 người bị tiêu diệt trước khi giết chết chiến binh hồn.",
	["SV_ACHIEVEMENT_DEAD_PEOPLE_NAME"] = "Tôi thấy người chết.",
	["SV_ACHIEVEMENT_DEATH_FROM_ABOVE_DESCRIPTION"] = "Tiêu diệt 100 kẻ địch bằng thiên thạch.",
	["SV_ACHIEVEMENT_DEATH_FROM_ABOVE_NAME"] = "Khủng hoảng từ trời xuống",
	["SV_ACHIEVEMENT_DEFEAT_COMPLETE_HARD_DESCRIPTION"] = "Hoàn thành chiến dịch ở độ khó Kỳ cựu.",
	["SV_ACHIEVEMENT_DEFEAT_COMPLETE_HARD_NAME"] = "Chăm sóc cao",
