	["TIP_13"] = "Nhấp vào biểu tượng đợt quái tiếp theo để xem chi tiết của kẻ địch tấn công sóng này.",
	["TIP_14"] = "Sử dụng quân đội hoặc doanh trại có thể tách biệt một kẻ địch khó khăn.",
	["TIP_15"] = "Tăng cường các loại cây gậy cũ của người bảo vệ rừng có thể gây sát thương chuẩn cho kẻ địch.",
	["TIP_16"] = "Khả năng làm mát đặc biệt của anh hùng khác nhau. Hãy biết anh hùng của mình.",
	["TIP_17"] = "Tất cả các con mồ côi đều có chất chống độc.",
	["TIP_18"] = "Nhìn lại con thỏ: những kẻ địch tóc râu này rất dễ thương, những người lính không thể ngăn chặn.",
	["TIP_19"] = "Thậm chí khi tháp phòng thủ bị cấm, các binh sĩ sẽ tiếp tục chiến đấu để ngăn chặn kẻ địch.",
	["TIP_1_NAME"] = "Thông tin của kẻ địch",
	["TIP_2"] = "2 và 3 có khả năng tấn công từ xa đối đầu kẻ địch.",
	["TIP_20"] = "Hãy chú ý đến các yếu tố đặc biệt, đôi khi các chiến lược phát triển xung quanh chúng thường có hiệu quả tuyệt vời và thú vị!",
	["TIP_21"] = "Đặt doanh trại gần Druita để tối đa hóa tiềm năng sát thương của nó.",
	["TIP_22"] = "Tất cả các hiệu ứng điều trị cùng một lúc sẽ loại bỏ độc và bệnh tật.",
	["TIP_23"] = "Mỗi anh hùng có kỹ năng độc đáo, có thể kết hợp với chiến lược khác nhau.",
	["TIP_24"] = "Hãy nhớ để nhấp vào kẻ địch, đọc lời khuyên, để biết cách đối phó với họ.",
	["TIP_25"] = "Thật kỳ diệu khi bị thương đối với kẻ địch.",
	["TIP_26"] = "Khi các doanh trại được nâng cấp, một nhóm các binh sĩ mới sẽ chạy ra và chiến đấu thay cho những đồng chí mệt mỏi của họ.",
	["TIP_27"] = "Hãy để một làn sóng của kẻ địch đến sớm, mang lại cho bạn thêm tiền vàng và giảm kỹ năng của thời gian hồi.",
	["TIP_28"] = "Bạn có thể thay đổi điểm thu thập của doanh trại, để họ di chuyển đến một vị trí thuận lợi để bạn thực hiện chiến lược của riêng bạn.",
	["TIP_29"] = "Hãy chú ý đến cờ tiếp theo. Nhìn lại, bạn sẽ thấy thông tin về kẻ địch tiếp theo. Chuẩn bị sẵn sàng!",
	["TIP_2_NAME"] = "Sát thương phép",
	["TIP_3"] = "Các chiến binh và kẻ địch bị sát thương ít hơn.",
	["TIP_30"] = "Hầu hết các đòn đánh có thể gây hại cho kẻ địch bay, ngay cả khi không được nhắm mục tiêu trực tiếp.",
	["TIP_31"] = "Đôi khi bán tháp phòng thủ hiện không thể sử dụng, có thể cho bạn đủ tiền để vượt qua tình trạng căng thẳng.",
	["TIP_32"] = "Thường có hiệu quả tốt hơn so với việc xây dựng một tháp phòng thủ nhiều tầng.",
	["TIP_33"] = "Các kẻ địch không bị ngăn chặn, hầu hết các tháp không bắn vào họ.",
	["TIP_34"] = "Bạn có thể sử dụng các công cụ mạnh mẽ trong cửa hàng để chiến đấu với bạn. Nó có thể giúp biến toàn bộ chiến tranh!",
	["TIP_35"] = "Các kẻ địch và quân đội bị sát thương ít hơn.",
	["TIP_36"] = "Sử dụng các đòn đánh từ xa để hỗ trợ doanh trại, để tối đa hóa sự tiếp xúc của kẻ địch dưới sự tấn công.",
	["TIP_37"] = "Trợ giúp là cách tốt để chia tay quân địch.",
	["TIP_38"] = "Vũ khí hiệu quả nhất khi đối đầu kẻ địch.",
	["TIP_39"] = "Vị trí của trung tâm nổ súng bị sát thương nhất.",
	["TIP_3_NAME"] = "Nâng cấp doanh trại",
	["TIP_4"] = "Bóng đèn có thể gây sát thương diện rộng, vì vậy nó phù hợp nhất để chống lại một số lượng lớn kẻ địch dày đặc.",
	["TIP_40"] = "Sử dụng lực lượng hỗ trợ liên tục để làm chậm và làm sát thương kẻ địch.",
	["TIP_41"] = "Khi trời mưa, bạn phải nhắm mục tiêu vị trí của kẻ địch trước.",
	["TIP_42"] = "Sau khi nâng cấp \"tự hồi phục\", việc bán tháp sẽ chỉ mất 10%.",
	["TIP_43"] = "Đối phó với kẻ địch có vũ khí, thương tích ma thuật là cách tốt nhất.",
	["TIP_44"] = "Doanh trại không thể chặn kẻ địch bay, và phần lớn tháp pháo cũng không thể nhắm vào chúng.",
	["TIP_45"] = "Có kẻ địch chống lại ma thuật bị sát thương phép nhỏ hơn.",
	["TIP_46"] = "Đặt vị trí của các điểm thu thập quân đội để phát triển chiến lược tốt hơn.",
	["TIP_47"] = "Thỉnh thoảng xây dựng nhiều tháp phòng thủ hơn là nâng cấp nhiều tháp.",
	["TIP_48"] = "Giảm sát thương bị bỏ qua.",
	["TIP_49"] = "Tải về doanh trại, đào tạo quân đội mới ngay lập tức.",
	["TIP_4_NAME"] = "Gọi đợt địch sớm",
	["TIP_5"] = "Tháp phòng thủ không bị mất đi là một hành động khôn ngoan.",
	["TIP_50"] = "Lời kêu gọi một làn sóng của kẻ địch có thể nhận được tiền thưởng và giảm một chút thời gian hồi của phép thuật.",
	["TIP_51"] = "Mặc dù không thể nhắm mục tiêu trực tiếp vào kẻ địch bay, nhưng vụ nổ của nó có thể gây hại cho nó.",
	["TIP_52"] = "Sử dụng doanh trại hoặc quân sự hỗ trợ để tách biệt kẻ địch khó khăn.",
	["TIP_53"] = "Sau khi nâng cấp kỹ năng thích hợp, người hoang dã có thể đối đầu kẻ địch bay.",
	["TIP_54"] = "Các yếu tố đất rất mạnh, mỗi đòn đánh có thể gây sát thương diện rộng.",
	["TIP_55"] = "Tắt chuột trên biểu tượng đợt quái tiếp theo, bạn có thể xác nhận loại của kẻ địch đợt quái tiếp theo.",
	["TIP_56"] = "Các kẻ địch và quân đội bị sát thương ít hơn.",
	["TIP_57"] = "Sử dụng các đòn đánh từ xa để hỗ trợ doanh trại, để tối đa hóa sự tiếp xúc của kẻ địch dưới sự tấn công.",
	["TIP_58"] = "Trợ giúp là cách tốt để chia tay quân địch.",
	["TIP_59"] = "Vũ khí hiệu quả nhất khi đối đầu kẻ địch.",
	["TIP_5_TITLE"] = "Điểm tập kết",
	["TIP_6"] = "Thật là phù hợp nhất để đối đầu kẻ địch có vũ khí.",
	["TIP_60"] = "Vị trí của trung tâm nổ súng bị sát thương nhất.",
	["TIP_61"] = "Sử dụng lực lượng hỗ trợ liên tục để làm chậm và làm sát thương kẻ địch.",
	["TIP_62"] = "Khi trời mưa, bạn phải nhắm mục tiêu vị trí của kẻ địch trước.",
	["TIP_63"] = "Đặt lại số điểm nâng cấp là cách tốt để điều chỉnh chiến lược.",
	["TIP_64"] = "Đối phó với kẻ địch có vũ khí, thương tích ma thuật là cách tốt nhất.",
	["TIP_65"] = "Doanh trại không thể chặn kẻ địch bay, và phần lớn tháp pháo cũng không thể nhắm vào chúng.",
	["TIP_66"] = "Có kẻ địch chống lại ma thuật bị sát thương phép nhỏ hơn.",
	["TIP_67"] = "Đặt vị trí của các điểm thu thập quân đội để phát triển chiến lược tốt hơn.",
	["TIP_68"] = "Thỉnh thoảng xây dựng nhiều tháp phòng thủ hơn là nâng cấp nhiều tháp.",
	["TIP_69"] = "Cơn đau khủng khiếp có thể bị bỏ qua.",
	["TIP_6_TITLE"] = "Cờ báo đợt địch",
	["TIP_7"] = "Các chiến binh sẽ đào tạo quân đội mới ngay lập tức.",
	["TIP_70"] = "Lực lượng quân sự sẽ được đào tạo ngay lập tức.",
	["TIP_71"] = "Lời kêu gọi một làn sóng của kẻ địch có thể nhận được tiền thưởng và giảm một chút thời gian hồi của phép thuật.",
	["TIP_72"] = "Mặc dù súng không thể trực tiếp nhắm đến kẻ địch bay, nhưng vụ nổ của nó có thể gây hại cho nó.",
	["TIP_73"] = "Sử dụng doanh trại hoặc quân sự hỗ trợ để tách biệt kẻ địch khó khăn.",
	["TIP_74"] = "Đối phó với kẻ địch mạnh mẽ, kết quả giết người là một cách tốt.",
	["TIP_75"] = "Hãy nhìn vào những kẻ địch có thể can thiệp vào phòng thủ. Có thể có nhiều kẻ địch đến ngay.",
	["TIP_76"] = "Tắt chuột trên biểu tượng đợt quái tiếp theo, bạn có thể xác nhận loại của kẻ địch đợt quái tiếp theo.",
	["TIP_77"] = "Đừng sợ bán tháp phòng thủ, thay thế một tháp phù hợp hơn.",
	["TIP_78"] = "Sư Tử và Sư Tử sẽ trở lại với máu.",
	["TIP_79"] = "Lời kêu gọi trước một làn sóng của kẻ địch không thể làm giảm thời gian hồi của khả năng phòng thủ tháp.",
	["TIP_7_TITLE"] = "Tấn công diện rộng",
	["TIP_8"] = "Các trại không thể ngăn chặn kẻ địch bay, và cả Druita và Tháp Cây kỳ lạ cũng không thể nhắm mục tiêu chúng.",
	["TIP_80"] = "Đôi khi giữ một chút vàng để đối phó với kẻ địch bất ngờ là thông minh.",
	["TIP_81"] = "Các người hoang dã có khả năng tự hồi máu, và mỗi lần ăn thì họ trở nên mạnh mẽ hơn.",
	["TIP_82"] = "Cái chết sa mạc không thể gọi thảm khi bị chặn.",
	["TIP_83"] = "Thuốc của kẻ địch không phải là chết người. Để các binh sĩ bị nghiện rút lui để bảo vệ họ.",
	["TIP_84"] = "Chết không thể giết anh hùng.",
	["TIP_85"] = "Kết hợp với một vòng tròn Samantha có thể làm cho người tàn bạo gần như không thể đánh bại.",
	["TIP_8_TITLE"] = "Bán tháp phòng thủ",
	["TIP_9"] = "Địch có khả năng chống lại ma thuật bị sát thương ít hơn.",
